color0: color@1400b000 {
	compatible = "mediatek,mt2701-disp-color";
	reg = <0 0x1400b000 0 0x1000>;
	interrupts = <GIC_SPI 161 IRQ_TYPE_LEVEL_LOW>;   /* COLOR irq; verificar nº exacto en el GIC SPI del MT6582 - placeholder, el COLOR irq no es critico para bypass */
	power-domains = <&scpsys MT6582_POWER_DOMAIN_DISP>;  /* si hay scpsys; si no, omitir (LK deja DISP on) */
	clocks = <&disp_dummy_clk>;   /* fixed-clock stub, ver campo "clocks" */
	};

/* fixed-clock stub compartido por los bloques DISP (un solo nodo reutilizable) */
disp_dummy_clk: disp-dummy-clk {
	compatible = "fixed-clock";
	#clock-cells = <0>;
	clock-frequency = <156000000>;   /* valor nominal del disp_clk MT6582; el valor no importa, el COLOR no usa la freq */
	};

/* IMPRESCINDIBLE: el COLOR no aparece solo; se engancha via la pipeline en el nodo display/mmsys.
   En el nodo <&mmsys>/mediatek,mt2701-mmsys, la ruta debe ser OVL0 -> COLOR0 -> RDMA0 -> DSI0
   (la mmsys_default_routing_table de mt2701 ya enruta COLOR). El COLOR0 se referencia desde
   el array de la pipeline del crtc (mediatek,mtk_drm) como uno de los components. */

/* Reloj stub: el LK deja DISPSYS encendido; clk_ignore_unused ya está en bootargs.
 * mtk_mutex_prepare hace clk_prepare_enable(clk) -> sobre fixed-clock es no-op y retorna 0. */
/ {
    disp_mutex_clk: disp-mutex-clk {
        compatible = "fixed-clock";
        #clock-cells = <0>;
        clock-frequency = <26000000>;   /* valor nominal; irrelevante, no se programa nada */
    };
};

&{/soc} {
    /* MM_MUTEX MT6582 @ fisico 0x1400E000 (virt downstream 0xF400E000).
     * Rejilla idéntica a mt2701-disp-mutex. */
    disp_mutex: mutex@1400e000 {
        compatible = "mediatek,mt2701-disp-mutex";
        reg = <0x1400e000 0x1000>;
        interrupts = <GIC_SPI 132 IRQ_TYPE_LEVEL_LOW>;  /* VERIFICAR: MT6582_DISP_MUTEX_IRQ_ID; ds_ddp_drv.c usa MT6582_DISP_MUTEX_IRQ_ID. Buscar el numero exacto en mt6582 irq headers. El driver mtk-mutex NO registra IRQ (la usa mtk_drm via crtc), asi que 'interrupts' aqui es opcional/informativo. */
        clocks = <&disp_mutex_clk>;
        /* power-domains: NO declarar (no hay scpsys/genpd en este port). */
        status = "okay";
    };
};

/* NOTA: el consumidor real es el nodo display-subsystem / mediatek,mt2701-mmsys,
 * que referencia &disp_mutex via la lista de 'mutex' o lo obtiene por
 * mtk_mutex_get(dev) resolviendo el device por compatible. El mtk-mutex NO
 * aparece en el grafo de 'ports'; mtk_drm_drv lo localiza por su compatible
 * en la tabla mtk_ddp_matches del SoC (hay que añadir entrada MT6582 o
 * reutilizar la ruta mt2701 en mtk_drm_drv.c / mtk_drm_ddp_comp.c). */
